package vn.svframe.lively.navigation;

import net.minecraft.block.BlockState;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.util.math.BlockPos;import net.minecraft.util.math.Vec3d;import vn.svframe.lively.npc.NpcDefinition;import vn.svframe.lively.npc.NpcRuntime;import vn.svframe.lively.world.SemanticStructureRegistry;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
/** Main-thread budgeted world sampling + worker A* + main-thread body movement. */
public final class WorldNavigationService implements AutoCloseable {public enum Mode{GOTO,FOLLOW,ESCORT,FLEE,SCHEDULE}public record Status(UUID npcId,Mode mode,String world,Vec3d target,int remainingNodes,String phase,String reason){}
 private static final int SAMPLE_COLUMNS_PER_TICK=384,MAX_COLUMNS=18000,MAX_AXIS=128,MAX_Y_SPAN=16,REPATH_INTERVAL=30;private static final double DEFAULT_SPEED=.16D;private final NpcRuntime npcs;private final SemanticStructureRegistry structures;private final ExecutorService workers;private final ConcurrentHashMap<UUID,Task> tasks=new ConcurrentHashMap<>();private final AtomicLong revision=new AtomicLong();
 public WorldNavigationService(NpcRuntime npcs,SemanticStructureRegistry structures){this.npcs=npcs;this.structures=structures;int threads=Math.max(1,Math.min(3,Runtime.getRuntime().availableProcessors()/3));workers=Executors.newFixedThreadPool(threads,r->{Thread t=new Thread(r,"Lively-Navigation-Worker");t.setDaemon(true);return t;});}
 public boolean goTo(UUID id,String world,Vec3d target){return begin(id,Mode.GOTO,world,target,null,1.25D);}public boolean flee(UUID id,String world,Vec3d threat,double distance){Vec3d current=npcs.position(id).orElse(null);if(current==null)return false;Vec3d away=current.subtract(threat);if(away.lengthSquared()<.01D)away=new Vec3d(1,0,0);return begin(id,Mode.FLEE,world,current.add(away.normalize().multiply(Math.max(4D,Math.min(48D,distance)))),null,1D);}public boolean follow(UUID id,UUID target){NpcDefinition d=npcs.get(id).orElse(null);return d!=null&&begin(id,Mode.FOLLOW,d.world(),new Vec3d(d.x(),d.y(),d.z()),target,2.4D);}public boolean escort(UUID id,UUID target){NpcDefinition d=npcs.get(id).orElse(null);return d!=null&&begin(id,Mode.ESCORT,d.world(),new Vec3d(d.x(),d.y(),d.z()),target,2.2D);}public boolean goToStructure(UUID id,String structure){var s=structures.get(structure).orElse(null);if(s==null)return false;Vec3d point=structurePoint(s,"entrance").orElseGet(()->center(s.bounds()));return begin(id,Mode.SCHEDULE,s.bounds().world(),point,null,1.2D);}public boolean stop(UUID id){return tasks.remove(id)!=null;}public Optional<Status> status(UUID id){Task t=tasks.get(id);return t==null?Optional.empty():Optional.of(new Status(id,t.mode,t.world,t.target,t.path==null?0:Math.max(0,t.path.size()-t.pathIndex),t.phase,t.reason));}public int activeCount(){return tasks.size();}
 public void tick(MinecraftServer server){long tick=server.getTicks();for(Task task:List.copyOf(tasks.values())){if(task.cancelled||npcs.get(task.npcId).isEmpty()){tasks.remove(task.npcId,task);continue;}updateDynamicTarget(server,task,tick);if(task.builder!=null){sample(server,task);continue;}if(task.planning)continue;if(task.path==null||task.pathIndex>=task.path.size()){if(nearTarget(task)){if(task.mode==Mode.FOLLOW||task.mode==Mode.ESCORT)continue;task.phase="arrived";tasks.remove(task.npcId,task);continue;}startSnapshot(server,task);continue;}moveAlongPath(server,task,tick);}}
 private boolean begin(UUID id,Mode mode,String world,Vec3d target,UUID tracked,double stopDistance){NpcDefinition d=npcs.get(id).orElse(null);if(d==null||!d.spawned()||!d.aiEnabled())return false;Task t=new Task(id,revision.incrementAndGet(),mode,world,target,tracked,stopDistance);tasks.put(id,t);return true;}
 private void updateDynamicTarget(MinecraftServer server,Task task,long tick){if(task.trackedEntity==null||tick-task.lastTargetRefresh<10L)return;task.lastTargetRefresh=tick;Vec3d position=null;String world=null;ServerPlayerEntity p=server.getPlayerManager().getPlayer(task.trackedEntity);if(p!=null){position=p.getPos();world=p.getServerWorld().getRegistryKey().getValue().toString();}if(position==null){position=npcs.position(task.trackedEntity).orElse(null);world=npcs.worldKey(task.trackedEntity).orElse(null);}if(position==null||world==null){task.reason="tracked_target_unavailable";return;}boolean changed=!world.equals(task.world)||position.squaredDistanceTo(task.target)>4D;task.target=position;task.world=world;if(changed&&!nearTarget(task)&&tick-task.lastRepath>=REPATH_INTERVAL){task.path=null;task.builder=null;task.planning=false;task.lastRepath=tick;}}
 private void startSnapshot(MinecraftServer server,Task task){Vec3d current=npcs.position(task.npcId).orElse(null);String currentWorld=npcs.worldKey(task.npcId).orElse(null);if(current==null||currentWorld==null){task.reason="body_position_unavailable";tasks.remove(task.npcId,task);return;}if(!currentWorld.equals(task.world)){task.reason="cross_world_navigation_requires_teleport";tasks.remove(task.npcId,task);return;}ServerWorld world=world(server,task.world);if(world==null){task.reason="unknown_world";tasks.remove(task.npcId,task);return;}Vec3d segment=segmentTarget(current,task.target);int minX=(int)Math.floor(Math.min(current.x,segment.x))-6,maxX=(int)Math.floor(Math.max(current.x,segment.x))+6,minZ=(int)Math.floor(Math.min(current.z,segment.z))-6,maxZ=(int)Math.floor(Math.max(current.z,segment.z))+6;if(maxX-minX+1>MAX_AXIS||maxZ-minZ+1>MAX_AXIS||(maxX-minX+1)*(maxZ-minZ+1)>MAX_COLUMNS){task.reason="navigation_snapshot_too_large";tasks.remove(task.npcId,task);return;}int minY=Math.max(world.getBottomY()+1,(int)Math.floor(Math.min(current.y,segment.y))-5),maxY=Math.min(world.getTopY()-2,(int)Math.ceil(Math.max(current.y,segment.y))+5);if(maxY-minY+1>MAX_Y_SPAN){int c=(int)Math.floor(current.y);minY=Math.max(world.getBottomY()+1,c-MAX_Y_SPAN/2);maxY=minY+MAX_Y_SPAN-1;}task.builder=new SnapshotBuilder(task.revision,task.world,current,segment,minX,maxX,minZ,maxZ,minY,maxY);task.phase="sampling";task.reason="";}
 private void sample(MinecraftServer server,Task task){SnapshotBuilder b=task.builder;if(b==null)return;ServerWorld world=world(server,b.world);if(world==null){tasks.remove(task.npcId,task);return;}int budget=SAMPLE_COLUMNS_PER_TICK;while(budget-->0&&b.cursorX<=b.maxX){int x=b.cursorX,z=b.cursorZ;for(int y=b.minY;y<=b.maxY;y++){BlockPos feet=new BlockPos(x,y,z);if(walkable(world,feet))b.walkable.add(feet.asLong());}b.cursorZ++;if(b.cursorZ>b.maxZ){b.cursorZ=b.minZ;b.cursorX++;}}if(b.cursorX<=b.maxX)return;task.builder=null;task.planning=true;task.phase="planning";task.lastRepath=server.getTicks();WalkSnapshot snapshot=b.freeze();long expected=task.revision;workers.execute(()->{List<BlockPos> path=plan(snapshot);server.execute(()->{Task current=tasks.get(task.npcId);if(current!=task||current.revision!=expected||current.cancelled)return;current.planning=false;if(path.isEmpty()){current.reason="no_path";current.phase="blocked";return;}current.path=path;current.pathIndex=Math.min(1,path.size()-1);current.phase="moving";current.reason="";});});}
 private void moveAlongPath(MinecraftServer server,Task task,long tick){Vec3d current=npcs.position(task.npcId).orElse(null);if(current==null){tasks.remove(task.npcId,task);return;}BlockPos node=task.path.get(task.pathIndex);if(tick%10L==0L){ServerWorld w=world(server,task.world);if(w==null||!walkable(w,node)){task.path=null;task.reason="path_invalidated";task.phase="repath";return;}}Vec3d target=new Vec3d(node.getX()+.5D,node.getY(),node.getZ()+.5D),delta=target.subtract(current);double distance=delta.length();if(distance<.17D){task.pathIndex++;return;}double speed=navigationSpeed(task.npcId);Vec3d step=current.add(delta.normalize().multiply(Math.min(speed,distance)));float yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z)));if(!npcs.moveStep(server,task.npcId,task.world,step,yaw,pitch)){task.reason="body_move_rejected";tasks.remove(task.npcId,task);}}
 private double navigationSpeed(UUID id){return npcs.get(id).map(d->{try{return Math.max(.04D,Math.min(.45D,Double.parseDouble(d.metadata().getOrDefault("navigation.speed",Double.toString(DEFAULT_SPEED)))));}catch(NumberFormatException ignored){return DEFAULT_SPEED;}}).orElse(DEFAULT_SPEED);}private boolean nearTarget(Task t){Vec3d c=npcs.position(t.npcId).orElse(null);String w=npcs.worldKey(t.npcId).orElse(null);return c!=null&&t.world.equals(w)&&c.squaredDistanceTo(t.target)<=t.stopDistance*t.stopDistance;}private static Vec3d segmentTarget(Vec3d start,Vec3d goal){Vec3d d=goal.subtract(start);double h=Math.sqrt(d.x*d.x+d.z*d.z);if(h<=80D)return goal;double s=80D/h;return new Vec3d(start.x+d.x*s,start.y+d.y*s,start.z+d.z*s);}
 private static List<BlockPos> plan(WalkSnapshot s){long start=nearest(s.walkable,s.start),goal=nearest(s.walkable,s.goal);if(start==Long.MIN_VALUE||goal==Long.MIN_VALUE)return List.of();PriorityQueue<NodeScore> open=new PriorityQueue<>(Comparator.comparingDouble(NodeScore::f));Map<Long,Double> g=new HashMap<>();Map<Long,Long> prev=new HashMap<>();Set<Long> closed=new HashSet<>();g.put(start,0D);open.add(new NodeScore(start,heuristic(start,goal)));int visited=0;long deadline=System.nanoTime()+20_000_000L;while(!open.isEmpty()&&visited++<80000&&System.nanoTime()<deadline){long current=open.poll().pos;if(!closed.add(current))continue;if(current==goal)return reconstruct(prev,current);BlockPos p=BlockPos.fromLong(current);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){if(dx==0&&dz==0)continue;long next=neighbor(s.walkable,p,dx,dz);if(next==Long.MIN_VALUE||closed.contains(next))continue;if(dx!=0&&dz!=0&&(!hasHorizontal(s.walkable,p,dx,0)||!hasHorizontal(s.walkable,p,0,dz)))continue;BlockPos n=BlockPos.fromLong(next);double cost=(dx!=0&&dz!=0?1.414D:1D)+Math.max(0D,n.getY()-p.getY())*.35D,tentative=g.getOrDefault(current,Double.POSITIVE_INFINITY)+cost;if(tentative<g.getOrDefault(next,Double.POSITIVE_INFINITY)){g.put(next,tentative);prev.put(next,current);open.add(new NodeScore(next,tentative+heuristic(next,goal)));}}}return List.of();}
 private static long neighbor(Set<Long>w,BlockPos p,int dx,int dz){for(int dy:new int[]{0,1,-1,-2}){long value=BlockPos.asLong(p.getX()+dx,p.getY()+dy,p.getZ()+dz);if(w.contains(value))return value;}return Long.MIN_VALUE;}private static boolean hasHorizontal(Set<Long>w,BlockPos p,int dx,int dz){return neighbor(w,p,dx,dz)!=Long.MIN_VALUE;}private static long nearest(Set<Long>w,Vec3d pos){long best=Long.MIN_VALUE;double bd=Double.POSITIVE_INFINITY;for(long packed:w){BlockPos p=BlockPos.fromLong(packed);double dx=p.getX()+.5-pos.x,dy=p.getY()-pos.y,dz=p.getZ()+.5-pos.z,d=dx*dx+dy*dy+dz*dz;if(d<bd){bd=d;best=packed;}}return bd<=64D?best:Long.MIN_VALUE;}private static double heuristic(long a,long b){BlockPos x=BlockPos.fromLong(a),y=BlockPos.fromLong(b);return Math.abs(x.getX()-y.getX())+Math.abs(x.getZ()-y.getZ())+Math.abs(x.getY()-y.getY())*.4D;}private static List<BlockPos> reconstruct(Map<Long,Long>prev,long current){ArrayDeque<BlockPos> result=new ArrayDeque<>();result.addFirst(BlockPos.fromLong(current));while(prev.containsKey(current)){current=prev.get(current);result.addFirst(BlockPos.fromLong(current));}return List.copyOf(result);}
 private static boolean walkable(ServerWorld world,BlockPos feet){BlockPos head=feet.up(),below=feet.down();if(!world.isInBuildLimit(feet)||!world.isInBuildLimit(head)||!world.isInBuildLimit(below))return false;BlockState fs=world.getBlockState(feet),hs=world.getBlockState(head),bs=world.getBlockState(below);return fs.getCollisionShape(world,feet).isEmpty()&&hs.getCollisionShape(world,head).isEmpty()&&(!bs.getCollisionShape(world,below).isEmpty()||!world.getFluidState(feet).isEmpty());}
 private static Optional<Vec3d> structurePoint(SemanticStructureRegistry.Structure s,String key){String raw=s.points().get(key);if(raw==null)return Optional.empty();String[] p=raw.split(",");if(p.length!=3)return Optional.empty();try{return Optional.of(new Vec3d(Double.parseDouble(p[0]),Double.parseDouble(p[1]),Double.parseDouble(p[2])));}catch(NumberFormatException ignored){return Optional.empty();}}private static Vec3d center(SemanticStructureRegistry.Bounds b){return new Vec3d((b.minX()+b.maxX()+1)/2D,b.minY()+1D,(b.minZ()+b.maxZ()+1)/2D);}private static ServerWorld world(MinecraftServer server,String key){net.minecraft.util.Identifier id=net.minecraft.util.Identifier.tryParse(key);return id==null?null:server.getWorld(net.minecraft.registry.RegistryKey.of(net.minecraft.registry.RegistryKeys.WORLD,id));}
 @Override public void close(){workers.shutdownNow();tasks.clear();}
 private static final class Task{final UUID npcId;final long revision;final Mode mode;final UUID trackedEntity;final double stopDistance;volatile String world;volatile Vec3d target;volatile SnapshotBuilder builder;volatile boolean planning,cancelled;volatile List<BlockPos> path;volatile int pathIndex;volatile long lastTargetRefresh,lastRepath;volatile String phase="queued",reason="";Task(UUID id,long revision,Mode mode,String world,Vec3d target,UUID tracked,double stop){this.npcId=id;this.revision=revision;this.mode=mode;this.world=world;this.target=target;this.trackedEntity=tracked;this.stopDistance=stop;}}
 private static final class SnapshotBuilder{final long revision;final String world;final Vec3d start,goal;final int minX,maxX,minZ,maxZ,minY,maxY;final Set<Long> walkable=new HashSet<>();int cursorX,cursorZ;SnapshotBuilder(long rev,String world,Vec3d start,Vec3d goal,int minX,int maxX,int minZ,int maxZ,int minY,int maxY){revision=rev;this.world=world;this.start=start;this.goal=goal;this.minX=minX;this.maxX=maxX;this.minZ=minZ;this.maxZ=maxZ;this.minY=minY;this.maxY=maxY;cursorX=minX;cursorZ=minZ;}WalkSnapshot freeze(){return new WalkSnapshot(revision,world,start,goal,Set.copyOf(walkable));}}
 private record WalkSnapshot(long revision,String world,Vec3d start,Vec3d goal,Set<Long> walkable){}private record NodeScore(long pos,double f){}}
